<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';
import {declaredBackendRoutes,type IntegrationSettings,type IntegrationProduct,type BackendRecord} from '@kuaixie/sdk';
import {uiErrorMessage,t,formatDate} from '@kuaixie/i18n';
import {createAdminApi} from '../api/client';
const api=createAdminApi(),settings=ref<IntegrationSettings|null>(null),selected=ref<IntegrationProduct|null>(null),values=ref<Record<string,string>>({}),clear=ref<Record<string,boolean>>({}),enabled=ref(false),remark=ref(''),busy=ref(false),error=ref(''),notice=ref(''),search=ref(''),prefix=ref(''),deliveries=ref<BackendRecord[]>([]);
const modeKeys={implemented:'integration.mode.implemented',bridge:'integration.mode.bridge',reference_only:'integration.mode.reference_only'};const fieldKeys={missing:'integration.field.missing',stored:'integration.field.stored',unreadable:'integration.field.unreadable'};
const routes=computed(()=>declaredBackendRoutes.filter(r=>(r.method+' '+r.path).toLowerCase().includes(search.value.trim().toLowerCase())));
async function load(){busy.value=true;error.value='';try{settings.value=await api.integrations.settings();deliveries.value=await api.integrations.smsDeliveries()}catch(e){error.value=uiErrorMessage(e)}finally{busy.value=false}}
function edit(p:IntegrationProduct){selected.value=p;values.value=Object.fromEntries(p.fields.map(f=>[f.key,f.secret?'':f.value||'']));clear.value={};enabled.value=p.enabled;remark.value=p.remark;notice.value=''}
function bundle(){if(!/^[A-Z][A-Z0-9_]{2,39}$/.test(prefix.value)){error.value=t('integration.invalidPrefix');return}const fields=['APP_ID','MERCHANT_ID','MERCHANT_SERIAL','PLATFORM_SERIAL','PRIVATE_KEY_PEM','PLATFORM_PUBLIC_KEY_PEM','SIGNING_SECRET','BEARER_TOKEN','API_KEY'].map(key=>({key,secret:/PEM|SECRET|TOKEN|KEY/.test(key),required:false,configured:false,status:'missing' as const}));const existing=settings.value?.products.find(p=>p.vendor==='credentials'&&p.code===prefix.value);edit(existing||{vendor:'credentials',code:prefix.value,category:'credentials',mode:'implemented',docs:'',enabled:false,remark:'',updatedAt:'',fields})}
async function save(){if(!selected.value||busy.value)return;if(!window.confirm(t('integration.confirmSave')))return;busy.value=true;error.value='';try{const removed=Object.entries(clear.value).filter(([,v])=>v).map(([k])=>k);const input=Object.fromEntries(Object.entries(values.value).filter(([key,value])=>value.trim()&&!removed.includes(key)));await api.integrations.save(selected.value.vendor,selected.value.code,{enabled:enabled.value,remark:remark.value,values:input,clearFields:removed});selected.value=null;values.value={};clear.value={};notice.value=t('integration.saved');await load()}catch(e){error.value=uiErrorMessage(e)}finally{busy.value=false}}
onMounted(load);
</script>
<template><section class="api-hub"><h2>{{$t('integration.title')}}</h2><p>{{$t('integration.help')}}</p><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><button :disabled="busy" @click="load">{{$t('common.retry')}}</button><p v-if="settings&&!settings.encryptionReady" role="alert">{{$t('integration.keyRequired')}}</p><nav><a href="#payment-settings">{{$t('integration.payments')}}</a><a href="#insurance-settings">{{$t('insurance.settings')}}</a></nav>
<template v-if="settings"><p v-if="settings.nativeDeliveryManaged">{{$t('integration.nativeManaged')}}</p><div class="bundle"><label>{{$t('integration.bundlePrefix')}}<input v-model="prefix" maxlength="40" placeholder="WECHAT_MAIN"/></label><button :disabled="busy||!settings.encryptionReady" @click="bundle">{{$t('integration.editBundle')}}</button></div><div class="products"><article v-for="product in settings.products" :key="product.vendor+'/'+product.code"><strong>{{product.vendor}} / {{product.code}}</strong><small>{{product.category}} · {{$t(modeKeys[product.mode])}} · {{$t(product.enabled?'insurance.enabled':'insurance.notConnected')}}</small><a v-if="product.docs" :href="product.docs" target="_blank" rel="noopener noreferrer">{{$t('integration.docs')}}</a><button :disabled="busy" @click="edit(product)">{{$t('product.edit')}}</button></article></div>
<form v-if="selected" @submit.prevent="save" autocomplete="off"><h3>{{selected.vendor}} / {{selected.code}}</h3><p>{{$t('integration.secretHelp')}}</p><label v-for="field in selected.fields" :key="field.key">{{field.key}} · {{$t(fieldKeys[field.status])}}<textarea v-if="field.key.endsWith('_PEM')" v-model="values[field.key]" :disabled="busy||clear[field.key]" maxlength="16000" spellcheck="false"/><input v-else v-model="values[field.key]" :type="field.secret?'password':'text'" :disabled="busy||clear[field.key]" maxlength="16000" autocomplete="off"/><span v-if="field.configured"><input v-model="clear[field.key]" type="checkbox" :disabled="busy"/>{{$t('integration.clear')}}</span></label><label>{{$t('integration.remark')}}<input v-model="remark" maxlength="200"/></label><label><input v-model="enabled" type="checkbox" :disabled="selected.mode==='reference_only'||busy"/>{{$t('insurance.enable')}}</label><button :disabled="busy||!settings.encryptionReady">{{$t('account.save')}}</button><button type="button" :disabled="busy" @click="selected=null;values={}">{{$t('product.cancel')}}</button></form>
<details><summary>{{$t('integration.smsHistory')}}</summary><p>{{$t('integration.smsNotice')}}</p><article v-for="row in deliveries" :key="String(row.id)"><span>{{row.id}} · {{row.channel}} · {{row.status}}</span><span>{{row.error||''}} · {{formatDate(String(row.updated_at||''))}}</span></article></details></template>
<details><summary>{{$t('integration.internalApis')}} ({{declaredBackendRoutes.length}})</summary><p>{{$t('integration.internalNotice')}}</p><input v-model="search" :placeholder="$t('integration.search')"/><div class="route" v-for="route in routes" :key="route.method+route.path"><code>{{route.method}} {{route.path}}</code></div></details></section></template>
<style scoped>.api-hub{padding:24px;background:var(--kx-surface,#fff);border:1px solid #cbd5e1;border-radius:18px;margin:20px 0}.api-hub p,.api-hub small{font-size:13px;line-height:1.7}.api-hub nav,.bundle{display:flex;gap:18px;flex-wrap:wrap;margin:16px 0}.products{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}.api-hub article{display:grid;gap:7px;padding:14px;border:1px solid #e2e8f0;border-radius:9px}.api-hub form{display:grid;gap:12px;margin:20px 0;padding:20px;border:1px solid #0e7490}.api-hub label{display:grid;gap:6px}.api-hub input,.api-hub textarea{padding:10px;max-width:100%;border:1px solid #cbd5e1;border-radius:8px}.api-hub textarea{min-height:100px}.api-hub button{padding:10px 14px;background:#0e7490;color:white;border:0;border-radius:8px}.api-hub details{margin-top:20px}.route{padding:8px;overflow-wrap:anywhere}.api-hub [role=alert]{color:#b42318}</style>
